// view-details.js — Busy Bucket Partner App · Booking Details interactions

document.addEventListener('DOMContentLoaded', function () {

  /* ---------------- Customer call button ---------------- */
  var customerCallBtn = document.getElementById('customerCallBtn');
  if (customerCallBtn) {
    customerCallBtn.addEventListener('click', function () {
      var phone = customerCallBtn.getAttribute('data-phone');
      if (phone) {
        window.location.href = 'tel:' + phone;
      }
    });
  }

  /* ---------------- Start Job — live selfie gate ---------------- */
  var startJobModal = document.getElementById('startJobModal');
  var startJobCloseBtn = document.getElementById('startJobCloseBtn');
  var selfieBox = document.getElementById('selfieBox');
  var selfieFileInput = document.getElementById('selfieFileInput');
  var selfieStatus = document.getElementById('selfieStatus');
  var startJobBtn = document.getElementById('startJobBtn');
  var lockHint = document.getElementById('lockHint');
  var selfieCaptured = false;

  function unlockJobActions() {
    var pestBtn = document.getElementById('pestReadyBtn');
    var cleanCheck = document.getElementById('cleaningPaidCheck');
    var acCheck = document.getElementById('acPaidCheck');
    if (pestBtn) pestBtn.disabled = false;
    if (cleanCheck) cleanCheck.disabled = false;
    if (acCheck) acCheck.disabled = false;
    if (lockHint) lockHint.classList.add('unlocked');
  }

  if (selfieBox && selfieFileInput) {
    selfieBox.addEventListener('click', function () {
      selfieFileInput.click();
    });
    selfieFileInput.addEventListener('change', function () {
      if (selfieFileInput.files && selfieFileInput.files[0]) {
        var reader = new FileReader();
        reader.onload = function (e) {
          selfieBox.innerHTML = '<img src="' + e.target.result + '" alt="Live selfie">';
        };
        reader.readAsDataURL(selfieFileInput.files[0]);
        selfieCaptured = true;
        if (selfieStatus) {
          selfieStatus.textContent = 'Photo capture ho gayi ✓';
          selfieStatus.classList.add('done');
        }
        if (startJobBtn) startJobBtn.disabled = false;
      }
    });
  }

  if (startJobBtn) {
    startJobBtn.addEventListener('click', function () {
      if (!selfieCaptured) return;
      if (startJobModal) startJobModal.classList.add('hidden');
      unlockJobActions();
      goToPaymentPage();
    });
  }

  // Skip/close — cancels this attempt to open Payment & Review; partner stays
  // on the Booking Details page and can tap "Payment aur Review" again later.
  if (startJobCloseBtn && startJobModal) {
    startJobCloseBtn.addEventListener('click', function () {
      startJobModal.classList.add('hidden');
    });
  }

  /* ---------------- Pest Control "Ready" -> mark done ---------------- */
  var pestReadyBtn = document.getElementById('pestReadyBtn');
  if (pestReadyBtn) {
    pestReadyBtn.addEventListener('click', function () {
      if (pestReadyBtn.disabled) return;
      if (pestReadyBtn.classList.contains('done')) return;
      pestReadyBtn.textContent = 'Done';
      pestReadyBtn.classList.remove('ready');
      pestReadyBtn.classList.add('done');
      var row = pestReadyBtn.closest('.service-detail-row');
      if (row) row.classList.add('row-done');
    });
  }

  /* ---------------- Home Deep Cleaning / AC Service: payment-gated "Done" ---------------- */
  function wirePaymentGatedDone(checkboxId, buttonId) {
    var checkbox = document.getElementById(checkboxId);
    var btn = document.getElementById(buttonId);
    if (!checkbox || !btn) return;

    checkbox.addEventListener('change', function () {
      btn.disabled = !checkbox.checked;
    });

    btn.addEventListener('click', function () {
      if (btn.disabled || btn.classList.contains('done')) return;
      btn.textContent = 'Completed';
      btn.classList.add('done');
      btn.disabled = true;
      checkbox.disabled = true;
      var row = btn.closest('.service-detail-row');
      if (row) row.classList.add('row-done');
    });
  }
  wirePaymentGatedDone('cleaningPaidCheck', 'cleaningDoneBtn');
  wirePaymentGatedDone('acPaidCheck', 'acDoneBtn');

  /* ---------------- Partner Live Location simulation ---------------- */
  var liveUpdatedText = document.getElementById('liveUpdatedText');
  var liveDistanceEl = document.getElementById('liveDistance');
  var liveEtaEl = document.getElementById('liveEta');

  var state = {
    lastUpdate: Date.now(),
    distanceKm: 1.6,
    etaMin: 6
  };

  function formatAgo() {
    var secs = Math.floor((Date.now() - state.lastUpdate) / 1000);
    if (secs < 60) return 'Live · updated just now';
    var mins = Math.floor(secs / 60);
    return 'Live · updated ' + mins + ' min ago';
  }

  function tickClock() {
    if (liveUpdatedText) liveUpdatedText.textContent = formatAgo();
  }

  function advancePartner() {
    if (state.distanceKm <= 0.2) {
      if (liveEtaEl) liveEtaEl.textContent = 'Partner has arrived at location';
      return;
    }

    var drop = Math.min(0.1, state.distanceKm - 0.2);
    state.distanceKm = +(state.distanceKm - drop).toFixed(2);
    state.etaMin = Math.max(1, state.etaMin - 1);
    state.lastUpdate = Date.now();

    if (liveDistanceEl) liveDistanceEl.textContent = state.distanceKm.toFixed(1) + ' km away';
    if (liveEtaEl) liveEtaEl.textContent = 'ETA ' + state.etaMin + ' min to Kotla Road';

    tickClock();
  }

  setInterval(tickClock, 1000);
  setInterval(advancePartner, 6000);

  /* ---------------- Payment & Review — swaps in as its own full page ---------------- */
  var viewDetailsPage = document.getElementById('viewDetailsPage');
  var paymentReviewPage = document.getElementById('paymentReviewPage');
  var openPaymentReviewBtn = document.getElementById('openPaymentReviewBtn');
  var backToDetailsBtn = document.getElementById('backToDetailsBtn');

  function goToPaymentPage() {
    if (!viewDetailsPage || !paymentReviewPage) return;
    viewDetailsPage.classList.remove('active');
    paymentReviewPage.classList.add('active');
  }

  if (openPaymentReviewBtn && startJobModal) {
    openPaymentReviewBtn.addEventListener('click', function () {
      // Live selfie ab yahan liya jaata hai — payment lene se pehle, payment
      // wale page par jaane se theek pehle — first page load par nahi.
      startJobModal.classList.remove('hidden');
    });
  }
  if (backToDetailsBtn && viewDetailsPage && paymentReviewPage) {
    backToDetailsBtn.addEventListener('click', function () {
      paymentReviewPage.classList.remove('active');
      viewDetailsPage.classList.add('active');
    });
  }

  /* ---------------- Payment mode toggle (Cash / UPI) + Scan-to-pay QR ---------------- */
  var cashModeBtn = document.getElementById('cashModeBtn');
  var upiModeBtn = document.getElementById('upiModeBtn');
  var upiUploadSection = document.getElementById('upiUploadSection');
  var markPaidBtn = document.getElementById('markPaidBtn');
  var amountDueEl = document.getElementById('amountDueValue');
  var qrImage = document.getElementById('qrImage');
  var qrBox = document.getElementById('qrBox');
  var qrStatus = document.getElementById('qrStatus');
  var qrStatusText = document.getElementById('qrStatusText');

  var TOTAL_AMOUNT = 2450;
  var payMode = 'upi'; // matches the active button in HTML
  var upiPaid = false;
  var autoDetectTimer = null;

  // Fixed scanner image (uploaded QR) — used for scan-to-pay in every payment mode.
  var QR_IMAGE_SRC = "data:image/png;base64,";

  function renderQr() {
    if (qrImage) qrImage.src = QR_IMAGE_SRC;
  }

  function startAutoDetect() {
    clearAutoDetect();
    autoDetectTimer = setTimeout(function () {
      markUpiPaid();
    }, 8000);
  }

  function clearAutoDetect() {
    if (autoDetectTimer) {
      clearTimeout(autoDetectTimer);
      autoDetectTimer = null;
    }
  }

  function markUpiPaid() {
    if (upiPaid) return;
    upiPaid = true;
    if (qrBox) qrBox.classList.add('paid');
    if (qrStatus) qrStatus.classList.add('paid');
    if (qrStatusText) qrStatusText.textContent = 'Payment mil gaya — auto-detected ✓';
    if (amountDueEl) amountDueEl.textContent = '₹0';
    if (markPaidBtn && payMode === 'upi') {
      markPaidBtn.textContent = 'Payment Received ✓';
      markPaidBtn.classList.add('done');
      markPaidBtn.disabled = true;
    }
  }

  function refreshMarkPaidState() {
    if (!markPaidBtn) return;
    if (markPaidBtn.classList.contains('done')) return;
    if (payMode === 'cash') {
      markPaidBtn.disabled = false;
      markPaidBtn.textContent = 'Payment Done';
    } else {
      // UPI: system auto-detects, so the manual button stays disabled while waiting.
      markPaidBtn.disabled = true;
      markPaidBtn.textContent = 'Payment Done';
    }
  }

  function setPayMode(newMode) {
    payMode = newMode;
    if (cashModeBtn) cashModeBtn.classList.toggle('active', payMode === 'cash');
    if (upiModeBtn) upiModeBtn.classList.toggle('active', payMode === 'upi');

    // Scanner ab Cash aur UPI dono mode mein dikhta rahega — sirf UPI ke liye hide nahi hoga.
    if (upiUploadSection) upiUploadSection.style.display = 'block';
    renderQr();

    if (payMode === 'upi') {
      if (!upiPaid) startAutoDetect();
    } else {
      clearAutoDetect();
    }
    refreshMarkPaidState();
  }

  if (cashModeBtn) cashModeBtn.addEventListener('click', function () { setPayMode('cash'); });
  if (upiModeBtn) upiModeBtn.addEventListener('click', function () { setPayMode('upi'); });

  /* Mark as Paid (cash flow — manual) */
  if (markPaidBtn) {
    markPaidBtn.addEventListener('click', function () {
      if (markPaidBtn.disabled || markPaidBtn.classList.contains('done')) return;
      markPaidBtn.textContent = 'Payment Received ✓';
      markPaidBtn.classList.add('done');
      if (amountDueEl) amountDueEl.textContent = '₹0';
    });
  }

  /* Review stars */
  var reviewStars = document.getElementById('reviewStars');
  if (reviewStars) {
    var starEls = reviewStars.querySelectorAll('span');
    reviewStars.addEventListener('click', function (e) {
      var target = e.target.closest('span[data-v]');
      if (!target) return;
      var val = parseInt(target.getAttribute('data-v'), 10);
      starEls.forEach(function (s) {
        s.classList.toggle('filled', parseInt(s.getAttribute('data-v'), 10) <= val);
      });
    });
  }

  /* Signature */
  var collectSignBtn = document.getElementById('collectSignBtn');
  if (collectSignBtn) {
    collectSignBtn.addEventListener('click', function () {
      if (collectSignBtn.classList.contains('done')) return;
      collectSignBtn.textContent = 'Signature Collected ✓';
      collectSignBtn.classList.add('done');
    });
  }

  /* Work Proof — live camera photo, then upload (unchanged) */
  var proofBox = document.getElementById('proofBox');
  var proofFileInput = document.getElementById('proofFileInput');
  var proofStatus = document.getElementById('proofStatus');
  var uploadProofBtn = document.getElementById('uploadProofBtn');
  var proofCaptured = false;

  if (proofBox && proofFileInput) {
    proofBox.addEventListener('click', function () {
      proofFileInput.click();
    });

    proofFileInput.addEventListener('change', function () {
      if (proofFileInput.files && proofFileInput.files[0]) {
        var reader = new FileReader();
        reader.onload = function (e) {
          proofBox.classList.add('filled');
          proofBox.innerHTML = '<img class="cap-preview" src="' + e.target.result + '" alt="Work proof photo">';
        };
        reader.readAsDataURL(proofFileInput.files[0]);
        proofCaptured = true;
        if (proofStatus) proofStatus.textContent = 'Photo capture ho gayi — ab upload karein';
        if (uploadProofBtn) uploadProofBtn.disabled = false;
      }
    });
  }

  if (uploadProofBtn) {
    uploadProofBtn.addEventListener('click', function () {
      if (!proofCaptured || uploadProofBtn.classList.contains('done')) return;
      if (proofStatus) {
        proofStatus.textContent = 'Proof photo upload ho gayi ✓';
        proofStatus.classList.add('done');
      }
      uploadProofBtn.textContent = 'Uploaded';
      uploadProofBtn.classList.add('done');
      uploadProofBtn.disabled = true;
    });
  }

  // Initialize QR + payment mode (UPI is default active mode; scanner now shows in both modes).
  setPayMode('upi');
});